'use strict';
function issueTrailsHTML(market=false){let trails=[['2002-06-19','안정환과 페루자'],['2005-06-22','박지성·이영표의 잉글랜드행'],['2009-01-13','카카를 향한 맨시티의 제안'],['2009-06-11','호날두의 여름'],['2010-10-22','루니의 거취 파동'],['2012-05-21','아자르 영입 경쟁'],['2012-08-15','판페르시와 두 구단'],['2013-07-24','수아레스의 계약 논쟁'],['2013-07-30','베일을 둘러싼 제안'],['2015-08-28','손흥민의 잉글랜드 진출'],['2017-07-18','네이마르의 2017년 여름'],['2017-08-11','쿠티뉴와 바르셀로나'],['2020-09-22','산초 협상의 시한'],['2020-08-26','메시의 이적 요구'],['2021-08-05','바르셀로나와 메시'],['2021-08-25','케인·음바페의 여름'],['2022-06-23','레반도프스키의 선택']];if(!market)trails=[['1999-05-26','캄 노우의 밤'],['2012-05-13','맨체스터의 마지막 날'],['2015-05-27','FIFA 수사'],['2018-09-01','아시안게임 금메달'],['2024-02-15','대표팀 감독 교체 논쟁'],['2018-06-27','한국·독일전의 파장'],['2021-04-18','슈퍼리그 논쟁'],...trails];return `<details class="issue-trails"><summary>이슈를 골라 첫 보도부터 따라가기 <small>이동한 날짜의 기사만 표시합니다.</small></summary><div>${trails.map(([d,t])=>'<button data-goto="'+d+'"><time>'+d+'</time><b>'+t+'</b><span>그날로 이동 ↗</span></button>').join('')}</div></details>`}
function newsCoverageHTML(){let stats=NewsCatalogue?.stats;if(!stats)return '';let years=Object.entries(stats.coverageByYear||{});return `<div class="panel"><h2>신문·이적 보도·사건 연표의 수록 범위</h2><div class="coverage"><div><b>${stats.editorialReports.toLocaleString()}</b><small>날짜와 내용을 따로 확인한 한국어 심층 편집 기사</small></div><div><b>${stats.archiveLinks.toLocaleString()}</b><small>날짜별 원문 보도 색인 · 기사 본문 수와 구분</small></div><div><b>${stats.historicalRecords.toLocaleString()}</b><small>사건일 기준의 역사 기록 · 당일 기사와 별도</small></div></div><p>뉴스는 선택 날짜와 발행일이 같은 항목만 표시합니다. 날짜별 매체 아카이브, Wikinews의 발행일, 이적 보도 연구자료를 구분해 기록합니다. 당시 지면의 원래 발행일이 명시된 재수록 기사는 원래 날짜로 보여주고 웹 재수록 날짜를 별도로 표시합니다.</p><p>신문사의 기사 전체를 복제하지 않습니다. 심층 기사는 한국어로 직접 편집한 짧은 요약·배경·당시 입장·쟁점이며, 원문 색인은 제목과 링크를 제공합니다. 번역된 색인에는 자동 번역을 표시하고, 번역을 얻지 못한 항목은 원문 제목을 보존합니다. 모든 기사와 모든 지역을 빠짐없이 수집했다는 뜻은 아닙니다.</p><p>역사 기록은 1956년 이후를 다루지만 시대·국가별 자료 밀도는 균일하지 않습니다. 날짜가 없거나 서로 충돌하는 기록을 임의의 날짜로 채우지 않습니다. 오래된 신문, 유료·삭제된 기사, 비공개 협상과 전체 여론은 이 자료만으로 완전하게 재현할 수 없습니다.</p><details class="coverage-years"><summary>연도별 실제 수록량 확인</summary><div class="table-wrap"><table><thead><tr><th>연도</th><th>원문 보도</th><th>심층 편집</th><th>사건 기록</th></tr></thead><tbody>${years.map(([y,v])=>'<tr><td>'+y+'</td><td>'+Number(v.articles||0).toLocaleString()+'</td><td>'+Number(v.editorials||0).toLocaleString()+'</td><td>'+Number(v.events||0).toLocaleString()+'</td></tr>').join('')}</tbody></table></div></details><p><a class="source-link" href="replay/news/index.json" target="_blank" rel="noopener">수록량·날짜·출처 메타데이터 ↗</a> · <a class="source-link" href="replay/news/quality.json" target="_blank" rel="noopener">자료 품질과 누락 범위 ↗</a> · <a class="source-link" href="replay/news/recovery-index.json" target="_blank" rel="noopener">접근 불가·복구 대기 원문 목록 ↗</a></p><p>뉴스 월별 데이터는 약 ${Math.round(stats.monthlyDataBytes/1048576)}MiB이며, 가장 큰 달은 ${Math.ceil(stats.largestMonthBytes/1024)}KiB입니다. 선택한 달만 불러오고 최근 6개월까지만 캐시합니다. 현재 용량 때문에 자료를 잘라내지는 않았습니다. 더 늘어나면 연도별 저장소 또는 별도 파일 저장소로 나눌 수 있습니다.</p><p><a class="source-link" href="https://github.com/chanmin6785-hue/1415-/blob/main/DATA_COVERAGE.md" target="_blank" rel="noopener">시대별 공백·언어·용량과 확장 대안 읽기 ↗</a></p><h3>보도와 역사 자료의 출처</h3><ul class="source-list"><li><a href="https://www.theguardian.com/football" target="_blank" rel="noopener">The Guardian · 날짜별 축구 보도 아카이브</a> — 원문 링크와 제목 색인</li><li><a href="https://www.skysports.com/football" target="_blank" rel="noopener">Sky Sports</a>, <a href="https://www.uefa.com/" target="_blank" rel="noopener">UEFA</a> 및 구단 발표 — 개별 심층 기사에 원문 표시</li><li><a href="https://en.wikinews.org/wiki/Category:Football_(soccer)" target="_blank" rel="noopener">Wikinews 기여자의 공개 뉴스</a> — 발행 시기에 따라 CC BY 2.5 / CC BY 4.0 또는 퍼블릭 도메인</li><li><a href="https://github.com/dcaled/FTR-18" target="_blank" rel="noopener">Danielle Caled·Mário J. Silva · FTR-18</a> — 2018년 여름의 다국어 이적 보도 출처·발행일 자료. 나중에 판명된 참·거짓 라벨은 화면에 사용하지 않습니다.</li><li><a href="https://en.wikipedia.org/wiki/Portal:Current_events" target="_blank" rel="noopener">위키백과 기여자 · 월별 시사 기록과 축구 시즌 일지</a> — <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>에 따른 번역·정리. 각 기록의 원문에서 기여 이력을 확인할 수 있습니다.</li></ul></div>`}
